INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA 06: Road to FIFA World Cup', 'You can experience the excitement of international soccer competition in FIFA 06. Extensive coaching options give you the opportunity to take control of all of your players on the pitch and determine their formation and strategy. FIFA 06 offers game modes ranging from a tournament to individual skill games. You can also play with real players from famous international teams from around the world. Multiplayer modes let you challenge other gamers.' FROM games WHERE igdb_id = 22342 ON CONFLICT (game_id, language_code) DO NOTHING;
