INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hammer-and-sickle', 22581, '2005-12-05', 58, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2x88.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsoi8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hammer & Sickle', 'Hammer & Sickle is a turn-based strategy game with role playing elements that uses the Silent Storm engine and universe. The year is 1949, with the Cold War between the US and Soviet Union looming and both sides uneasy at the thought of an atomic war occurring. The player takes the role of a Soviet commando on an undercover mission to meet a contact in Allied-occupied Germany. However, things go badly for this meeting, leaving the protagonist without proper support, equipment, and identification papers. Behind Allied-occupied lines, the player must attempt to stop a rogue third party intent on initiating World War III between the US and Russia.
