INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jump Super Stars', 'Jump Super Stars is a 2D fighting game for the Nintendo DS. It was developed by Ganbarion and published by Nintendo. The game was released on August 8, 2005 in Japan and accompanied the release of a red Nintendo DS. A sequel, Jump Ultimate Stars, was released in Japan on November 23, 2006.' FROM games WHERE igdb_id = 28835 ON CONFLICT (game_id, language_code) DO NOTHING;
