INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close Combat: First to Fight', 'Close Combat: First to Fight is an authentic, team-based first-person shooter created under the direction of active-duty United States Marines fresh from the front lines of combat in Iraq and Afghanistan. Set in a modern mid-eastern urban battleground, players lead a four-man Marine fire team through the perils of modern urban combat. Together with the United States Marine Corps and Atomic Games, Destineer has created First to Fight as a training simulation for use by the Marine Corps and has now made it available to gamers.' FROM games WHERE igdb_id = 5779 ON CONFLICT (game_id, language_code) DO NOTHING;
