INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Gotham Racing 3', 'Project Gotham Racing 3 (PGR3 for short) is an arcade-style racing game that was released with the launch of the Xbox 360 on November 22, 2005 for the US market and December 2, 2005 in Europe, and was released on January 12, 2006 in Japan. Developed by Bizarre Creations, it is the third installment in the Project Gotham Racing series. Project Gotham Racing 3 was rated by Official Xbox Magazine (OXM) to be Xbox 360 "Game Of The Year" (2005). OXM also rated it "Best 1st Person (Not Shooter) of the Year", because of its realistic inside-car view.' FROM games WHERE igdb_id = 3322 ON CONFLICT (game_id, language_code) DO NOTHING;
