INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pathologic', 'Pathologic (known in Russian as Мор. Утопия) is an award winning 2005 psychological horror video game developed by the Russian studio Ice-Pick Lodge. It was published in Russia and other CIS-countries by Buka Entertainment. The game was published in the UK on 18 August 2006 by G2 Games. The game was remastered for Microsoft Windows and self-published in 2015 as Pathologic Classic HD, with a remake/sequel, Pathologic 2, coming in 2019.' FROM games WHERE igdb_id = 8074 ON CONFLICT (game_id, language_code) DO NOTHING;
