INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Serious Sam II', 'The iconic Serious Sam brings his trademark relentless intensity to this bigger, bolder, more colorful sequel to the classic Serious Sam: First and Second Encounters! Tasked with rescuing the universe one bullet at a time against overwhelming hordes of time traveling enemies, Serious Sam must battle through thick jungles, murky swamps, frozen tundra, and futuristic cities to bring down Mental and his vile armies. Serious Sam 2 is a shot of adrenaline to the hearts of first-person shooter fans across the world. This is serious!' FROM games WHERE igdb_id = 787 ON CONFLICT (game_id, language_code) DO NOTHING;
