INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-football-06', 5952, '2005-07-11', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rnb.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Football 06', 'NCAA Football ''06, known colloquially as College Football 2006, is a collegiate American football video game which was released on July 11, 2005. It is the successor to NCAA Football 2005 in the NCAA Football series. The product features former Michigan Wolverines standout and Heisman Trophy winner Desmond Howard on the cover. He is the only cover athlete not to have played the year before their respective game; Howard last played at Michigan in 1991. It is the only game in the series as of 2013 to have a music soundtrack, as the other games play school fight songs and general band pieces, and the last game in the series to feature FCS (Division 1-AA) teams.' FROM games WHERE igdb_id = 5952 ON CONFLICT (game_id, language_code) DO NOTHING;
