INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-men-legends-ii-rise-of-apocalypse', 4576, '2005-09-20', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pf0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scj8qe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men Legends II: Rise of Apocalypse', 'X-Men Legends II: Rise of Apocalypse is an action role-playing game and a sequel to X-Men Legends. The player controls a party of four characters, though only one at a time can be controlled directly. Besides switching the characters for combat purposes, the player is often obliged to do so, because some of the tasks in the game require the specific abilities of a certain mutant. For example, Iceman can put out the fire, Magneto can generate a metal bridge across a gap, etc. Most of the time, however, is spent in combat, collecting loot and acquiring experience points. Unlike the first game, items dropped by enemies are random. The character will level up, become stronger, and learn new skills. The player can opt to allocate all the experience and skill points manually.' FROM games WHERE igdb_id = 4576 ON CONFLICT (game_id, language_code) DO NOTHING;
