INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon XD: Gale of Darkness', 'Pokemon XD is a sequel to the role-playing game Pokémon Colosseum. You''ll play as Michael, a Pokémon trainer who is trying to thwart the evil Cipher. Cipher plans to control the world by using the powerful, but unpredictable, shadow Pokémon. Now you must fight back by collecting your own shadow Pokémon and beating Cipher''s goons in battle. Pokémon XD also lets you import Pokémon from Game Boy Advance Pokémon games and participate in head-to-head battles with other players.' FROM games WHERE igdb_id = 2724 ON CONFLICT (game_id, language_code) DO NOTHING;
