INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Spider-Man', 'Based on the comic book of the same name, Ultimate Spider-Man lets you play as either the hero Spider-Man or his arch-nemesis, Venom. Use the unique combat techniques of either Spider-Man or Venom to battle a host of Spider-Man characters. Artistic contributions by the creators of the series make for an authentic Spider-Man experience.' FROM games WHERE igdb_id = 4225 ON CONFLICT (game_id, language_code) DO NOTHING;
