INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phoenix Wright: Ace Attorney', 'Meet Phoenix Wright, the rookie defense lawyer new to the scene with the wildest cross-examination skills in town! Take on five intriguing cases to reveal dramatic, stunning, and even comical court proceedings. Use both the touch screen to investigate the crime scenes, question witnesses and present shocking evidence. “Objection!”...It’s outrageous fun! You won’t be able to put down this laugh-out-loud, riveting adventure!' FROM games WHERE igdb_id = 1426 ON CONFLICT (game_id, language_code) DO NOTHING;
