INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: The Lampshade of No Real Significance', 'A fan-made parody flash video game originally created for Newgrounds by The Super Flash Bros. The game parodies the Legend of Zelda series, with the gameplay consisting of one lengthy trading sequence, a typical convention in the series.' FROM games WHERE igdb_id = 210328 ON CONFLICT (game_id, language_code) DO NOTHING;
