INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms 4: Mayhem', 'The Worms series continues with Worms 4: Mayhem. You can engage in the turn-based combat that the series has become known for across predesigned or random 3D maps. Worms 4: Mayhem delivers new weapons as well as more customization options, allowing you to design your teams and the arsenal that they use. You can unlock bonuses in the 25-mission story mode or play online against up to four other players.' FROM games WHERE igdb_id = 6244 ON CONFLICT (game_id, language_code) DO NOTHING;
