INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Nemesis: Rise of the Imperfects', 'Marvel Nemesis: Rise of the Imperfects pits fierce Marvel superheroes against each other in a 3D fighting game. You can assume control of heroes such as the Punisher, Spider-Man, and Captain America, and duel with them in interactive and destructible environments. A new team of superheroes called the Imperfects joins the mayhem. You can play in single-player story mode to unlock collectible awards, or you can play against other gamers in multiplayer modes.' FROM games WHERE igdb_id = 3992 ON CONFLICT (game_id, language_code) DO NOTHING;
