INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ape Escape: On the Loose', 'Based on the Ape Escape series, Ape Escape: On the Loose arrives on the PSP with multiplayer functionality and a variety of minigames. The new adventure begins when Specter--a monkey-turned-monster--and his army of monkeys travel back in time to change history and take over the world. Now it''s up to you to pursue Specter and capture more than 200 monkeys in eight different worlds, which span more than 20 levels.' FROM games WHERE igdb_id = 44530 ON CONFLICT (game_id, language_code) DO NOTHING;
