INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battalion Wars', 'A global conflict has reached a stalemate in the console version of the Game Boy Advance series Advance Wars. The evil Kaiser Vlad, seeking to take advantage of the standoff, has assembled an army of shock troops, forcing The Western Frontier and the Tundran Territories to ally and fight back. Battalion Wars is a real-time strategy game that lets you control teams of soldiers and vehicles and lead them through more than 20 missions, using a variety of weapons and tactics.' FROM games WHERE igdb_id = 3797 ON CONFLICT (game_id, language_code) DO NOTHING;
