INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amped 3', 'The Amped snowboarding series lets you take to the slopes again with Amped 3. This game features a redesigned control scheme, many new tricks and challenges, and the ability to play as a skier. Play through story mode to both increase your skills and earn the respect of your fellow riders in an attempt to clear your name of a false accusation' FROM games WHERE igdb_id = 5483 ON CONFLICT (game_id, language_code) DO NOTHING;
