INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogger: Ancient Shadow', 'Frogger is Back to His Classic Beginnings. His home of Firefly Swamp is being overrun by Dr. Wani and his evil plans. Join Frogger in his latest adventure as he explores seven different worlds and tries to restore order to his beloved swamp. Features classic, addictive "hop and dodge" gameplay. Mini games with up to 4 players on all platforms. Over 30 levels of play. Wide range of character moves, such as the double jump, tongue grab, and more. Special bonus - orignial 1981 Frogger arcade game included on all platforms.' FROM games WHERE igdb_id = 3924 ON CONFLICT (game_id, language_code) DO NOTHING;
