INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball GT: Transformation', 'Dragon Ball GT: Transformation is a Game Boy Advance action game based on the Japanese cartoon Dragon Ball GT. Transformation follows the Dragon Ball GT storyline from the Child Goku Saga to the Baby Saga. You can create three-man teams from seven playable characters--such as Goku, Trunks, and Uub--and choose who you control in the middle of a battle.' FROM games WHERE igdb_id = 24269 ON CONFLICT (game_id, language_code) DO NOTHING;
