INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy IV Advance', 'Final Fantasy IV Advance is largely based on the WonderSwan Color version. Some changes include the addition of character portraits in text boxes, the ability to switch party members, increased difficulty, and new dungeons with new items and weapons along with new bosses. The script received a re-translation more faithful to the original material. The Quicksave, which allows the player to save the current position (regardless of where) in a file that is deleted upon loading, is featured.' FROM games WHERE igdb_id = 406 ON CONFLICT (game_id, language_code) DO NOTHING;
