INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vietcong-2', 3179, '2005-10-24', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xfl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5s95.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vietcong 2', 'Vietcong 2 is the next installment in the million+ selling Vietcong franchise, set against the background of the 1968 Tet Offensive during the Vietnam War. Brought to life through a gritty story written by well-known authors, compiled from first-hand accounts of Special Forces and Infantry servicemen stationed in Hue during the assault. Based on these historical accounts, the player will take the role of a US Captain tasked with escorting a war reporter covering the traditional New Year (Tet) festivities during a ceasefire. Follow the progress of the infamous Tet Offensive from joyous New Year celebrations in the US compound, through bloody conflict across 14 distinct locations, to the final push to reclaim the Imperial Palace and the city of Hue.' FROM games WHERE igdb_id = 3179 ON CONFLICT (game_id, language_code) DO NOTHING;
