INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts II', 'Kingdom Hearts II is an action role-playing game, and the primary entry to the series since the 2002 Disney Interactive and Square collaboration. The game''s setting is a collection of various levels (referred to in-game as "worlds") that the player progresses through. As in the first game, it II allows the player to travel to locales from various Disney works, along with original worlds specifically created for the series.' FROM games WHERE igdb_id = 1221 ON CONFLICT (game_id, language_code) DO NOTHING;
