INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR SimRacing', 'NASCAR SimRacing, abbreviated NSR, is a computer racing simulator developed by EA Tiburon and released on February 15, 2005, by EA Sports for Microsoft Windows. The game includes all of the 2004 NEXTEL Cup Series tracks including Pocono Raceway as an unlockable like in NASCAR 2005: Chase for the Cup The game cover features the vehicles of Ryan Newman, Ron Hornaday and Chad Chaffin on the cover.
