INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blitz-the-league', 5753, '2005-10-17', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70pg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zxiuqgpjtrzotilqm0cu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blitz: The League', 'Blitz: The League is an American football game by Midway as an unlicensed extension of their NFL Blitz series. Released after the NFL signed an exclusive licensing deal with Electronic Arts, it was released in October 2005 for the PlayStation 2 and Xbox. This game is the first in the Blitz series to receive an "M" rating by the ESRB due to the graphic violence, explicit language, and drug use depicted. Lawrence Taylor, who provides voice acting for the game, serves as its official spokesman. In 2006, a second version of the game was released on the Xbox 360 in October. In December 2006, a portable version was released on the PlayStation Portable (under the title Blitz: Overtime). These versions included the voicework and likeness of former pro linebacker Bill Romanowski. The game was originally intended to be a Wii launch title, but the Wii-version was delayed and eventually canceled.
