INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Club 3: DUB Edition', 'Midnight Club 3: DUB Edition is a racing game, developed by Rockstar San Diego and published by Rockstar Games, and is the third game in the Midnight Club series. Like previous installments in the series, the game is an arcade-style racer and focuses on wild, high-speed racing, rather than realistic physics and driving characteristics. The name derived from a partnership between Rockstar and DUB Magazine, which features heavily in the game in the form of DUB-sponsored races and DUB-customized vehicles as prizes.' FROM games WHERE igdb_id = 5928 ON CONFLICT (game_id, language_code) DO NOTHING;
