INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day of Defeat: Source', 'Day of Defeat offers intense online action gameplay set in Europe during WWII. Assume the role of infantry, sniper or machine-gunner classes, and more. DoD:S features enhanced graphics and sounds design to leverage the power of Source, Valve''s new engine technology.' FROM games WHERE igdb_id = 3267 ON CONFLICT (game_id, language_code) DO NOTHING;
