INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Dead: Regeneration', 'Evil Dead: Regeneration takes over where the film Evil Dead 2 left off. You can play as Ash, who has been committed to an insane asylum where a mad scientist is doing experiments with the Necronomican. With the help of some firepower and your new sidekick, a 3-foot tall "deadite," you can battle the scientist''s unholy creations and save civilization.' FROM games WHERE igdb_id = 5828 ON CONFLICT (game_id, language_code) DO NOTHING;
