INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harry-potter-and-the-goblet-of-fire', 3942, '2005-11-08', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20dq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccvw8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Goblet of Fire', 'Harry Potter and the Goblet of Fire is the fourth title in the Harry Potter franchise. It has a unique feel and gameplay with elements not present in any other game of the franchise, including a camera of a 3D environment that is not player-controlled and a system in which previous levels can be played again at will. Due to higher-quality graphics in comparison to previous Harry Potter video games, characters more closely resemble their movie counterparts. It was also the first Harry Potter game to feature a multiplayer mode.' FROM games WHERE igdb_id = 3942 ON CONFLICT (game_id, language_code) DO NOTHING;
