INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nano-breaker', 22305, '2005-01-27', 49, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oxm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqe96.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nano Breaker', 'In Nano Breaker''s futuristic world, nanomachines, which were originally developed to enrich humankind, suddenly went awry. The machines began to harvest the blood of humans and the iron of buildings in an effort to construct an army of monster machines. In order to combat this threat, you must slash your way through hordes of enemy units to save the world from apocalypse. Equipped with a powerful shape-shifting Plasma Blade, you assume the role of the lone hero, who must defend humankind from the deadly nanomachines.' FROM games WHERE igdb_id = 22305 ON CONFLICT (game_id, language_code) DO NOTHING;
