INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drill Dozer', 'In the platformer Drill Dozer, you can take the roll of Jill, the daughter of a crime boss who is set on revenge. When a rival gang steals away her family''s heirloom, Jill gives chase in her Drill Dozer, an upgradeable piece of power armor equipped with a large drill. This piece of equipment will help you navigate through six different areas, where you will encounter varied enemies and bosses.' FROM games WHERE igdb_id = 6390 ON CONFLICT (game_id, language_code) DO NOTHING;
