INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: The Sanctuary', 'Based on the popular anime series of the same name Saint Seiya: Chapter Sanctuary brings the legendary conflict between the Knights of Athena and the Knights of Ares home to the PlayStation 2. Battling over the Golden Cloth of Sagittarius, more than 20 different fighters square off against one another across several different modes including those of the Story, Versus, and Practice variety. As an added bonus, several of the show''s most memorable moments have been recreated using the latest in CG cinematics as well, with licensed voice-overs specifically re-recorded for the videogame version of the story. Available only in Japan.' FROM games WHERE igdb_id = 43345 ON CONFLICT (game_id, language_code) DO NOTHING;
