INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geometry Wars: Retro Evolved', 'Geometry Wars: Retro Evolved is a old school style shooter, but remixed for the 21st century with next generation graphics and deep, modern gameplay. Playing is simple: you are a geometric "ship" trapped in a grid world, facing off against waves of deadly wanderers, snakes, and repulsars. Your aim is to survive long enough to set a high score!' FROM games WHERE igdb_id = 15756 ON CONFLICT (game_id, language_code) DO NOTHING;
