INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ridge Racer DS', 'The Ridge Racer series returns with an all-new racing experience on the DS. The DS version lets you control your vehicle using the handheld''s touch screen and race in wireless multiplayer matches for up to six players. You can race on 20 tracks in three different locations, including the Ridge Racer cityscape, a Northwest course from Ridge Racer Revolution, and a desert area in the Southwest. With Ridge Racer DS, you can experience fast-paced racing action in the palm of your hand.' FROM games WHERE igdb_id = 20201 ON CONFLICT (game_id, language_code) DO NOTHING;
