INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Theft Auto: Liberty City Stories', 'Grand Theft Auto: Liberty City Stories is an action-adventure game set in Liberty City in 1998, serving as a prequel to Grand Theft Auto III. Players assume the role of Toni Cipriani, a member of the Leone crime family, as he returns from hiding to reestablish his position within the organization. The game features open-world exploration, mission-based progression, and various side activities, maintaining the series'' hallmark gameplay elements.' FROM games WHERE igdb_id = 3263 ON CONFLICT (game_id, language_code) DO NOTHING;
