INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crazy-chicken-the-good-the-egg-and-the-ugly--1', 79166, '2005-10-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coakhu.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Chicken: The Good, The Egg, and the Ugly', 'In this game Moorhuhn Indy has to take the precious "amulet of thingy" from the hidden temple of the jungle. But he is not alone on the way: a horde of wild gorillas, crocodiles and shamans seem to want to prevent the amulet from thingy from getting into the hands of an adventure treasure hunter. The chicken already has a lot to do against bats, creepy skeletons and spiders, but then it also encounters aliens who have settled in the deep jungle and are making the journey to the treasure more and more difficult for Moorhuhn Indy. But with courage, skill and a cool head you can succeed in guiding Moorhuhn Indy through the 21 levels to the precious amulet of thingy! There is also plenty of gold, gems and other valuable treasures to be found to fill your high score with.' FROM games WHERE igdb_id = 79166 ON CONFLICT (game_id, language_code) DO NOTHING;
