INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radiata Stories', 'Radiata Stories is a fantasy role-playing game set in a world where humans and fairies have peacefully coexisted. Now a war has broken out, and you must guide two young protagonists in a mission to save Radiata from destruction. Combat features a real-time link system in which multiple characters can combine abilities to form more powerful attacks. Radiata Stories also features an interactive environment and more than 175 characters that you can recruit to join and help you on your quest.' FROM games WHERE igdb_id = 19160 ON CONFLICT (game_id, language_code) DO NOTHING;
