INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon DS Cute', 'Harvest Moon DS Cute is the female version of Harvest Moon DS for the Nintendo DS. It was published and developed by Marvelous Interactive Inc., and first released in Japan on December 8, 2005. Harvest Moon DS Cute replaces the male protagonist from Harvest Moon DS with a female character; players may choose either Pony from Harvest Moon: Another Wonderful Life or Claire from Harvest Moon: More Friends of Mineral Town. The Japanese version introduced a system not present in the North American version known as the "Best Friend" system. This allowed the player to essentially marry any of the bachelorettes from Harvest Moon DS, as well as the bachelors.' FROM games WHERE igdb_id = 47699 ON CONFLICT (game_id, language_code) DO NOTHING;
