INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konjiki no Gash Bell!! Go! Go! Mamono Fight!!', 'Konjiki no Gash Bell!! Go! Go! Mamono Fight!! Konjiki no Gasshu Beru!! Gō! Gō! Mamono Fight!!, "Golden Gash Bell!! Go! Go! Demon Fight!!") is a video game for PlayStation 2 and GameCube which was developed by Eighting and was published by Bandai on December 15, 2005. The fighting gameplay style is similar to Super Smash Bros. with four-player multiplayer, as well as few other video games like Konjiki no Gash Bell!! Unare! Yūjō no Zakeru Dream Tag Tournament.' FROM games WHERE igdb_id = 124491 ON CONFLICT (game_id, language_code) DO NOTHING;
