INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince of Persia: The Two Thrones', 'I returned home expecting peace. Instead, I found my kingdom ravaged by war and my people enslaved. Now I am a fugitive, hunted by hostile armies and plagued by a curse that is gradually possessing my soul. A darker Prince resides in me now. And I must embrace his powers and skill if I want to restore peace to my land, my people, and my soul.' FROM games WHERE igdb_id = 2437 ON CONFLICT (game_id, language_code) DO NOTHING;
