INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Act of War: Direct Action', 'Act of War: Direct Action is a highly realistic, near future real-time strategy game, set against the backdrop of a conflict that threatens to permanently change the face of our world. Created in conjunction with US Air Force captain (ret.) Dale Brown, author of 14 New York Times best-sellers, this techno-thriller game puts you in control of Task Force Talon, a direct action team put together to defend cities around the globe. With the ultimate in authentic modern day weaponry, vehicles and intelligence at your disposal, no other game puts you in better control of tomorrow''s war!' FROM games WHERE igdb_id = 587 ON CONFLICT (game_id, language_code) DO NOTHING;
