INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EyeToy: Play 2', 'EyeToy: Play 2 is the sequel to the first EyeToy: Play game and includes 12 new mini-games to play using the EyeToy USB camera. Games include Mr Chef (making burgers for customers), Table Tennis (playing table tennis against AI opponent), Goal Attack (being a goal keeper) and many more. There are also over 75 bonus games to try out future possibilities of EyeToy technology.' FROM games WHERE igdb_id = 19842 ON CONFLICT (game_id, language_code) DO NOTHING;
