INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War World: Tactical Combat', 'War World is a 3D mech combat simulator game developed and published by Australian company Third Wave Games (who are made up of former Rare alumni who have been involved in the development of such games as Banjo Kazooie, Donkey Kong 64, and others). It was released on Microsoft Windows in 2005, and 2008 for the Xbox Live Arcade service.' FROM games WHERE igdb_id = 25985 ON CONFLICT (game_id, language_code) DO NOTHING;
