INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wallace & Gromit: The Curse of the Were-Rabbit', 'The main characters are Wallace and Gromit, whose new company, Anti-Pesto, is charged with keeping rabbits away from the upcoming Giant Vegetable Competition. Use the BunGun to suck up pests and shoot them into a drain to save the day!' FROM games WHERE igdb_id = 6227 ON CONFLICT (game_id, language_code) DO NOTHING;
