INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snood-2-on-vacation', 19107, '2005-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ced.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snood 2: On Vacation', 'We have arrived at Snoodville and the action is all go, go, go! Classic Snood turned sideways is a massive issue as all the snoods fall to the floor. Once they meet up with three of their own color, all the action starts to happen. Clear the board of all the snoods in time limit and other play modes. No more snoods available !! What do we do now? We fire a grappling hook to hook the snoods and pull them back to snood central! Then fire them to where we want them to be to make them fall from the board. Circular snood will also get you in a spin! Fire the snoods up to the highest levels, but watch out -- there are no straight sides to bounce off! You are in a circular tube and the snoods will bounce and fly everywhere if your angles are wrong. Just when you think you have the game beaten the whole world rotates and leaves you fighting to stay in the game!' FROM games WHERE igdb_id = 19107 ON CONFLICT (game_id, language_code) DO NOTHING;
