INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Digital Devil Saga 2', 'Digital Devil Saga: Avatar Tuner 2, released outside of Japan as Shin Megami Tensei: Digital Devil Saga 2, is a 2005 role-playing game for the PlayStation 2, and the second and final entry in the Digital Devil Saga series duology. It features new mechanics such as Berserk Mode and a changed Mantra grid system.' FROM games WHERE igdb_id = 18229 ON CONFLICT (game_id, language_code) DO NOTHING;
