INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal: Head-On', 'Twisted Metal: Head-On is a vehicular combat video game developed by Incognito Entertainment and released by Sony on March 24, 2005 for the PlayStation Portable and February 5, 2008 for the PlayStation 2. Head-On shares not only the distinction of being the seventh game released in the Twisted Metal series, but also is the first game in the series to ship fully online-enabled.' FROM games WHERE igdb_id = 5414 ON CONFLICT (game_id, language_code) DO NOTHING;
