INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Force Neo', 'Max completes his Force military training and returns to his village to meet his family and to find news of his missing brother. Later, the village is attacked by monsters later suspected as remnants of the Legion as well as the appearance of a mysterious figure that seems to know of his brother. This reasons compel Max to seek out the Legion threat, hoping in the process to also find his missing brother.' FROM games WHERE igdb_id = 22562 ON CONFLICT (game_id, language_code) DO NOTHING;
