INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enthusia: Professional Racing', 'Enthusia Professional Racing is the driving simulation that emphasizes skill behind the wheel, not under the hood. The game emphasizes pure driving skills and ensures that winning is a result of ability, not how much money you spent tuning a car. It''s real-world racing at its finest. Earn the #1 ranking by competing in races scheduled throughout the entire calendar year in Enthusia Life mode Weather effects that change driving dynamics, including rain and snow.' FROM games WHERE igdb_id = 19818 ON CONFLICT (game_id, language_code) DO NOTHING;
