INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Flashpoint: Elite', 'Operation Flashpoint: Elite immerses you in realistic Cold War military situations. Not only do you control and command squads and soldiers, but also land, sea, and air vehicles. You''ll have access to cars, APCs, tanks, and even military helicopters. The game''s open-ended environments let you experience different kinds of gameplay, whether you''re commanding a squad, driving tanks, transporting troops, piloting a helicopter, or taking on the role of a sniper.' FROM games WHERE igdb_id = 22567 ON CONFLICT (game_id, language_code) DO NOTHING;
