INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tork: Prehistoric Punk', 'Not even time can stand in the way of Tork. This cave boy must travel through time to find those responsible for kidnapping his father and destroying his village. Not your ordinary hero, Tork can change into three spirit animals: a yeti, an armadillo, or a flying squirrel. As Tork, you must face dinosaurs, gargoyles, robots, and more as you fight your way from the Stone Age to the Age of Fantastical Machines. Dodge avalanches, volcanoes, and machines in a variety of fantastic environments.' FROM games WHERE igdb_id = 6206 ON CONFLICT (game_id, language_code) DO NOTHING;
