INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tekken 5: Dark Resurrection', 'The hugely popular arcade and console fighting game, Tekken 5: Dark Resurrection is now available with an all-new ONLINE BATTLE feature! Take on other players from around the country, in full HD running at a smooth 60 frames per second! Prove who the real King of the Iron Fist Tournament is by checking the online rankings. Experience the pinnacle of fighting games as Tekken reaches into the "Online Vs." world for the first time ever!' FROM games WHERE igdb_id = 1235 ON CONFLICT (game_id, language_code) DO NOTHING;
