INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meteos', 'An evil planet named Meteo is sending storms of world-ending meteors across the galaxy, and only your puzzle skills can stop them. As blocks drop down on the lower screen, you must use the DS''s stylus to match up blocks of the same color. Once you have enough blocks connected, they''ll shoot back into the sky to form planets on the upper screen.' FROM games WHERE igdb_id = 1165 ON CONFLICT (game_id, language_code) DO NOTHING;
