INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-state-of-war', 12299, '2005-12-08', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nz5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6wah.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors: State of War', 'Samurai Warriors: State of War is a portable version of Samurai Warriors, however, it is not a straight conversion and is made to more resemble Dynasty Warriors, giving it an "Samurai Warriors Empires" style of playing. The gameflow is mainly separated into two stages: the Strategy phase and the Action phase. During the first stage, the map is separated into colored squares and the player is asked to move their character in a turn-based fashion. Terrain affects how the player can act during this stage. What usually follows is the action phase, which asks the player to defeat as many opponents possible within 60 seconds. These stages can tip the battle in the player''s favor. There are four main armies for the player to participate in: the Takeda (Western), Uesugi (Eastern), Nobunaga, or the solo army. Completing the game with these four factions unlocks the final stage in the game. It guest stars characters from Dynasty Warriors 4. The game features a Story mode, Free mode and VS mode.' FROM games WHERE igdb_id = 12299 ON CONFLICT (game_id, language_code) DO NOTHING;
