INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myst V: End of Ages', 'Myst V: End of Ages is a 2005 adventure video game, and the fifth and final installment in the Myst series. As in previous games in the series, End of Ages''s gameplay consists of navigating worlds known as "Ages" via the use of special books and items which act as portals. On each Age, the player solves puzzles and discovers story clues hidden in the Ages or written down in diaries and journals. The player''s actions in the game decide the fate of the ancient D''ni civilization.' FROM games WHERE igdb_id = 8475 ON CONFLICT (game_id, language_code) DO NOTHING;
