INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredibles: Rise of the Underminer', 'The Incredibles: Rise of the Underminer continues the story from the first Pixar film, following Mr. Incredible and Frozone as they pursue the Underminer through underground tunnels to prevent his world domination scheme. Players can switch between both superheroes or team up in cooperative play, with each character offering distinct abilities that evolve throughout the campaign. While the main heroes venture below ground, the rest of the Incredible family handles surface-level threats, creating parallel storylines that expand the movie''s universe.' FROM games WHERE igdb_id = 3955 ON CONFLICT (game_id, language_code) DO NOTHING;
