INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Bowling', 'Midnight Bowling is a bowling video game by Gameloft originally released for mobile phones. A version with enhanced graphics was also released for WiiWare, and under the name Midnight Bowling 3D for phones. It is part of Gameloft''s Midnight series, which includes Midnight Pool, Midnight Casino and Midnight Hold''em Poker, and the game was also included in the Midnight Play! Pack compilation for the Nintendo DS. In November 2008, it was made available for the iOS via Apple''s App Store.' FROM games WHERE igdb_id = 21802 ON CONFLICT (game_id, language_code) DO NOTHING;
