INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Genesis: Dragon Song', 'Set in an expansive fantasy universe and beautifully presented in a rich, vibrant visual style, the world of Lunar has seen a number of versions across several formats, spanning 14 years and three generations of hardware. Set a thousand years before previous storylines, Lunar Genesis tells the tale of a band of young adventurers performing courier jobs who stumble into a battle between the forces of good and evil. This battle threatens to consume the entire land and sets the stage for over 70 hours of handheld RPG adventuring.' FROM games WHERE igdb_id = 85266 ON CONFLICT (game_id, language_code) DO NOTHING;
