INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: The Dome', 'This third installment of the SingStar series brings yet another bundle of songs to sing along. New to this game is the compatibility with EyeToy and a few rapping parts in the songs.' FROM games WHERE igdb_id = 15093 ON CONFLICT (game_id, language_code) DO NOTHING;
