INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sakura-wars-so-long-my-love', 5136, '2005-07-07', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w43.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/br0d1ehhsssuvnuw660t.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Wars: So Long, My Love', 'Sakura Wars is a Strategy RPG that features a unique sim-based story system. An in-depth storyline exists, much like in any other RPG; however, the player''s destiny in the game is not predetermined. Character interaction plays a major role, and your responses to the various characters in the game can ultimately change the story content and even the final outcome. The battle system is divided into two main parts; ground combat and air combat. Ground combat takes place using two-legged mechanized suits, which transform into jet fighters to take the fight to the sky. Every mech unit in the game can transform from battle mech mode to jet fighter mode during combat. Once transformed, weapons and movement methods will change as well. For example, the hero''s ground mode utilizes a sword as his main weapon, but in jet mode he will use long-range missiles.' FROM games WHERE igdb_id = 5136 ON CONFLICT (game_id, language_code) DO NOTHING;
