INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: ''80s', 'The main focus of the game is singing those songs as good as one can. The game gives points which are distributed by the purity of singing, as in how well does one manage to stay on tune. It doesn''t matter if you change octaves in the middle of the song or what words are you singing in (it doesn''t have a word recognition), so your singing is rated by how well you manage to hit the correct note at the correct time.' FROM games WHERE igdb_id = 15094 ON CONFLICT (game_id, language_code) DO NOTHING;
