INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz! The Music Quiz', 'Buzz!: The Music Quiz is the first in the Buzz! series of video games created by Sleepydog and Relentless Software and published by Sony Computer Entertainment Europe''s XDev for the PlayStation 2. In the game, players answer questions asked by the quizmaster (also called Buzz) using the four Buzz! remote controls. The game was part of Sony''s "Fire It Up" campaign, which also includes the EyeToy and SingStar systems.' FROM games WHERE igdb_id = 18715 ON CONFLICT (game_id, language_code) DO NOTHING;
