INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet: Deadlocked', 'Ratchet: Deadlocked is the fourth game in the Ratchet & Clank series by Insomniac Games. Deadlocked is different in its counterparts in that it focuses more on shooting than platforming and puzzle elements. The game allows you to use two bots to fight along side you, which can be upgraded over time with better weapons and firepower.
