INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Tennis: Power Tour', 'Players can test their backhand in this unique role-playing tennis adventure. Train hard at the Royal Tennis Academy to be a champion. Gain experience and improve your skills through lessons and tournaments, and rise to the top of the ranks. Play as Mario, Peach, Waluigi, or Donkey Kong in a slew of wild modes. Advance through the story and unlock even more characters, all with their own power moves. Beat Mario at his own game, then link up with a friend or three for even more frantic fun.' FROM games WHERE igdb_id = 6504 ON CONFLICT (game_id, language_code) DO NOTHING;
